size_t WritePSDChannelBlob(const PSDInfo *psd_info, const ImageInfo *image_info,
                           Image *image, Image *next_image, QuantumType quantum_type,
                           unsigned char *compact_pixels, MagickOffsetType size_offset,
                           MagickBooleanType separate, ExceptionInfo *exception) {
  size_t count = 0;
  MagickBooleanType status = MagickTrue;
  size_t y;
  ssize_t number_pixels = 0;
  unsigned char *pixels = NULL;
  size_t length = 0;

  if (image->depth == 1)
    status = WritePSD1BitChannelBlob(psd_info, image_info, image, next_image, quantum_type,
                                     compact_pixels, size_offset, separate, exception);

  for (y = 0; y < (ssize_t) image->rows; y++) {
    pixels = GetAuthenticPixels(next_image, 0, y, next_image->columns, 1, exception);
    if (pixels == (unsigned char *) NULL)
      continue;
    length = ExportQuantumPixels(next_image, (CacheView *) NULL, (Image *) NULL, quantum_type,
                                  compact_pixels, exception);
    if (length == 0)
      continue;
    if (length != (size_t) (next_image->columns * sizeof(*compact_pixels)))
      continue;
    count += length;
  }

  if (length != 0) {
    if (psd_info->compression == PSDCompressionRLE)
      count += WriteOnePSDChannelRLEBlob(psd_info, image_info, image, next_image, quantum_type,
                                         compact_pixels, size_offset, separate, exception);
    else if (psd_info->compression == PSDCompressionZip)
      count += WriteOnePSDChannelZipBlob(psd_info, image_info, image, next_image, quantum_type,
                                         compact_pixels, size_offset, separate, exception);
  }

  return count;
}

