size_t WritePSDChannelBlob(const PSDInfo *psd_info, const ImageInfo *image_info,
                           Image *image, Image *next_image, QuantumType quantum_type,
                           unsigned char *compact_pixels, MagickOffsetType size_offset,
                           MagickBooleanType separate, ExceptionInfo *exception) {
  size_t written = 0;
  size_t rows = image->rows;
  size_t columns = image->columns;
  size_t depth = image->depth;
  size_t length;
  size_t count;
  ssize_t y;
  register ssize_t x;
  register Quantum *p;
  unsigned char *pixels = (unsigned char *) AcquireQuantumMemory(columns, sizeof(*pixels));

  if (pixels == (unsigned char *) NULL) {
    (void) ThrowMagickException(exception, GetMagickModule(), ResourceLimitError,
                                "MemoryAllocationFailed", "Unable to allocate pixels");
    return 0;
  }

  if ((psd_info->compression == RLECompression) || (psd_info->compression == ZIPCompression))
    for (y = 0; y < (ssize_t) rows; y++) {
      p = GetPixelInfoPixel(image_info, quantum_type, image, 0, y, exception);
      for (x = 0; x < (ssize_t) columns; x++) {
        *pixels = (unsigned char) ((MagickOffsetType) ScaleQuantumToChar(*p));
        pixels++;
        p += GetPixelInfoChannels(image_info, quantum_type, image);
      }

      if (psd_info->compression == RLECompression)
        length = WriteRLECompression(pixels - columns, columns, compact_pixels + written);
      else {
        length = CompressData(pixels - columns, columns, compact_pixels + written, ZIPMethod);
        if (length == 0) {
          (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
                                      "PSDCompressionError", "Unable to compress data");
          written = 0;
          break;
        }
      }

      written += length;
    }

  if (pixels != (unsigned char *) NULL)
    pixels = (unsigned char *) RelinquishMagickMemory(pixels);

  return written;
}

