size_t WritePSDChannelBlob(const PSDInfo *psd_info, const ImageInfo *image_info,
                           Image *image, Image *next_image,
                           QuantumType quantum_type, unsigned char *compact_pixels,
                           MagickOffsetType size_offset, MagickBooleanType separate,
                           ExceptionInfo *exception) {
  size_t bytes_written = 0;

  if (image_info->depth == 1)
    return 0;

  for (size_t y = 0; y < image->rows; y++) {
    MagickBooleanType status;
    Quantum *pixels = (Quantum *)AcquireQuantumMemory(image->columns, sizeof(Quantum));

    if (pixels == (Quantum *)NULL) {
      ThrowBinaryException(ResourceLimitError, "UnableToAcquireMemory", image->filename);
    }

    ExportPixels(image, 0, y, image->columns, 1, quantum_type, pixels, exception);

    if (psd_info->compression == 0) {
      status = WriteBlobMemory(image, image->columns, pixels);
    } else {
      size_t compressed_length;
      unsigned char *compressed_pixels = (unsigned char *)RLECompress(pixels,
        image->columns, &compressed_length);

      if (compressed_pixels != NULL) {
        status = WriteBlobMemory(image, compressed_length, compressed_pixels);
        compressed_pixels = (unsigned char *)RelinquishMagickMemory(compressed_pixels);
      } else {
        status = MagickFalse;
      }
    }

    if (!status) {
      pixels = (Quantum *)RelinquishMagickMemory(pixels);
      ThrowBinaryException(CorruptImageError, "UnableToWritePSDChannel", image->filename);
    }

    pixels = (Quantum *)RelinquishMagickMemory(pixels);
    bytes_written += image->columns;
  }

  return bytes_written;
}
